const input = $input.first().json;
const body = input.body || input;
const { nombre, apellido, whatsapp, email, telefono, lead_tipo, categoria, nivel, objetivo, disponibilidad, notas, horario_id } = body;

if (!nombre) {
  throw new Error('Falta el campo requerido: nombre');
}
if (!whatsapp) {
  throw new Error('Falta el campo requerido: whatsapp');
}

const esc = (v) => v === null || v === undefined || v === '' ? null : String(v).replace(/'/g, "''");
const asSql = (v) => v === null ? 'null' : `'${v}'`;

const nom = esc(nombre);
const ap = esc(apellido);
const wa = esc(whatsapp);
const em = esc(email);
const tel = esc(telefono);
const lt = esc(lead_tipo);
const cat = esc(categoria);
const niv = esc(nivel);
const obj = esc(objetivo);
const disp = esc(disponibilidad);
const not = esc(notas);
const horId = horario_id ? parseInt(horario_id) : null;

const query = `INSERT INTO alumnos (nombre, apellido, whatsapp, email, telefono, lead_tipo, categoria, nivel, objetivo, disponibilidad, notas, estado, estado_motivo, estado_fecha, primer_contacto, ultimo_contacto, created_at, updated_at, activo)
VALUES (${asSql(nom)}, ${asSql(ap)}, ${asSql(wa)}, ${asSql(em)}, ${asSql(tel)}, ${asSql(lt)}, ${asSql(cat)}, ${asSql(niv)}, ${asSql(obj)}, ${asSql(disp)}, ${asSql(not)}, 'ACTIVO', 'Alumno/tutor existente registrado por el agente (no pasó por el funnel de leads)', CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, CURRENT_TIMESTAMP, true)
RETURNING id, nombre, whatsapp, estado;`;

return [{ json: { query, horario_id: horId } }];

const alumno = $input.first().json;
const prev = $('Build Query Insert Alumno').first().json;
const horarioId = prev.horario_id;

// Si vino horario_id, linkeamos alumnos_horarios e incrementamos el cupo.
// Si no vino, ejecutamos un SELECT inofensivo para no romper la cadena
// de nodos (no hace falta un IF separado para este caso).
let query;
if (horarioId) {
  query = `INSERT INTO alumnos_horarios (alumno_id, horario_id, fecha_inscripcion, activo) VALUES (${alumno.id}, ${horarioId}, CURRENT_TIMESTAMP, true);\nUPDATE horarios SET cupo_actual = COALESCE(cupo_actual, 0) + 1, updated_at = CURRENT_TIMESTAMP WHERE id = ${horarioId};`;
} else {
  query = 'SELECT 1;';
}

return [{ json: { query, alumno_id: alumno.id, alumno_nombre: alumno.nombre, alumno_whatsapp: alumno.whatsapp, alumno_estado: alumno.estado, horario_id: horarioId } }];

const prev = $('Build Query Vincular Horario').first().json;

return [{
  json: {
    success: true,
    message: 'Alumno/tutor existente registrado correctamente',
    alumno: {
      id: prev.alumno_id,
      nombre: prev.alumno_nombre,
      whatsapp: prev.alumno_whatsapp,
      estado: prev.alumno_estado
    },
    horario_id: prev.horario_id || null
  }
}];
